// Public token (the tokenizer's output model).
type Token struct {
	Kind, Text string
	Off, End   int
	Nl         bool
	Kid, Lid   uint16
}

// LexError reports input the lexer cannot tokenize. Tokenize returns it; ParseWith and the
// Doc constructors panic with it.
type LexError struct {
	Off int
	Msg string
}

func (e *LexError) Error() string { return e.Msg }

// Tokenize is the lexer alone: a fresh slice the caller owns.
func Tokenize(src string) (toks []Token, err error) {
	defer func() {
		if r := recover(); r != nil {
			le, ok := r.(*LexError)
			if !ok { panic(r) }
			toks, err = nil, le
		}
	}()
	slim := lex(src)
	out := make([]Token, len(slim))
	for i := range slim {
		t := &slim[i]
		out[i] = Token{Kind: tokKind(t), Text: tokText(src, t), Off: int(t.Off), End: int(t.End), Nl: t.Nl, Kid: t.Kid, Lid: t.Lid}
	}
	return out, nil
}

