		p.scratch = append(p.scratch, expr)
		next := p.peek()
		if next == nil { p.pos = save; p.scratch = p.scratch[:sb]; p.nodes = p.nodes[:nb]; p.kids = p.kids[:kb]; return -1 }
		if next.Kid == 18 { p.pushLeaf(18, uint32(p.pos)); p.pos++; continue }
