func (p *parserW) parseTopOneW() (spanned, bool) {
	{ sp := p.pos; fr, ok := p.parseDeclW(); if ok { return fr, true }; p.pos = sp }
	{ sp := p.pos; fr, ok := p.parseStmtW(); if ok { return fr, true }; p.pos = sp }
	return spanned{}, false
}
func (p *parserW) parseProgramW() (spanned, bool) {
	save := p.pos; sb := len(p.scratch)
	capHint := (len(p.toks) - p.pos) / 2
	if capHint < 8 { capHint = 8 }
	localE := make([]EntryMeta, 0, capHint)
	for {
		sp := p.pos
		p.maxLook = 0
		fr, ok := p.parseTopOneW()
		if !ok { p.pos = sp; break }
		tokEnd := p.pos
		ext := tokEnd
		if p.maxLook > ext { ext = p.maxLook }
		end := int(fr.off)
		if fr.present {
			_, e1 := p.b.SpanOf(fr.h, p.toks)
			end = int(e1)
			localE = append(localE, EntryMeta{int(fr.tokStart), tokEnd, ext, int(fr.off), end, len(p.scratch) - sb, 1})
			p.scratch = append(p.scratch, fr.h)
		}
	}
	p.entryHs = append([]int32(nil), p.scratch[sb:]...)
	p.entries = localE
	return p.finishW(29, sb, p.offAtW(save), save), true
}

// parseWithCst: concrete hot path — the native engine building into the builder's arena.
// Keeps ParseWith(CstBuilder) within the additive-prefix / byte-equal contract
// without paying for a second method-instantiation (Go GC-shape stenciling tax).
func parseWithCst(src string, b *CstBuilder) (int32, bool) {
	p := &engine{nodes: b.Nodes[:0], kids: b.Kids[:0]}
	h := p.parse(src, lex(src))
	b.Nodes, b.Kids, b.Toks = p.nodes, p.kids, p.toks
	if h < 0 { return 0, false }
	return h, true
}
func parseWithW(src string, b Builder) (int32, bool) {
	p := &parserW{toks: lex(src), src: src, b: b, scratch: nil}
	fr, ok := p.parseProgramW()
	recordToks(b, p.toks)
	if !ok || p.pos != len(p.toks) || !fr.present { return 0, false }
	return fr.h, true
}

// ParseWith runs the builder-driven parse. *CstBuilder uses the concrete hot path (the native
// engine); other Builders (e.g. *SlimBuilder) use interface parserW.
// ok=false is reject (distinct from a leaf handle, which may also be negative).
func ParseWith(src string, b Builder) (h int32, ok bool) {
	if cb, is := b.(*CstBuilder); is {
		return parseWithCst(src, cb)
	}
	return parseWithW(src, b)
}

func writeKidWith(nodes []Node, kids []int32, toks []Tok, v int32, b *strings.Builder) {
	if v < 0 {
		ti, tt := decodeLeaf(v)
		t := toks[ti]
		fmt.Fprintf(b, "{\"tokenType\":%q,\"offset\":%d,\"end\":%d}", TT_NAMES[tt], t.Off, t.End)
		return
	}
	writeJSONWith(nodes, kids, toks, v, b)
}
func writeJSONWith(nodes []Node, kids []int32, toks []Tok, id int32, b *strings.Builder) {
	nd := &nodes[id]
	fmt.Fprintf(b, "{\"rule\":%q,\"children\":[", RULE_NAMES[nd.RuleId])
	for i := uint32(0); i < nd.KidCount; i++ {
		if i > 0 { b.WriteByte(',') }
		writeKidWith(nodes, kids, toks, kids[nd.KidStart+i], b)
	}
	fmt.Fprintf(b, "],\"offset\":%d,\"end\":%d}", nd.Offset, nd.End)
}


// shiftHandle mutates a consumer builder arena (or returns a shifted leaf handle).
func shiftHandle(nodes []Node, kids *[]int32, h int32, byteDelta, tokDelta int) int32 {
	if h < 0 {
		ti, tt := decodeLeaf(h)
		return encodeLeaf(uint32(int32(ti)+int32(tokDelta)), tt)
	}
	nd := &nodes[h]
	nd.Offset = uint32(int32(nd.Offset) + int32(byteDelta))
	nd.End = uint32(int32(nd.End) + int32(byteDelta))
	nd.TokStart = uint32(int32(nd.TokStart) + int32(tokDelta))
	nd.TokEnd = uint32(int32(nd.TokEnd) + int32(tokDelta))
	nd.Ext = uint32(int32(nd.Ext) + int32(tokDelta))
	for i := uint32(0); i < nd.KidCount; i++ {
		slot := nd.KidStart + i
		cid := (*kids)[slot]
		if cid < 0 {
			ti, tt := decodeLeaf(cid)
			(*kids)[slot] = encodeLeaf(uint32(int32(ti)+int32(tokDelta)), tt)
		} else {
			shiftHandle(nodes, kids, cid, byteDelta, tokDelta)
		}
	}
	return h
}
func (b *CstBuilder) Shift(h int32, byteDelta, tokDelta int) int32 {
	return shiftHandle(b.Nodes, &b.Kids, h, byteDelta, tokDelta)
}

func parseWithMetaW(text string, meta []alignMeta, b Builder) (h int32, entries []EntryMeta, entryHs []int32, toks []Tok, ok bool) {
	p := &parserW{toks: toksFromMeta(text, meta), src: text, b: b, scratch: nil}
	fr, pok := p.parseProgramW()
	recordToks(b, p.toks)
	if !pok || p.pos != len(p.toks) || !fr.present {
		return 0, nil, nil, p.toks, false
	}
	return fr.h, append([]EntryMeta(nil), p.entries...), append([]int32(nil), p.entryHs...), p.toks, true
}

func tryReuseTopW(b Builder, sh Shifter, oldHs []int32, oldEntries []EntryMeta, oldP []Tok, oldMeta []alignMeta, newText string, newMeta []alignMeta, byteDelta, oldN, prefix, suffix int) (root int32, newEntries []EntryMeta, newHs []int32, newToks []Tok, reused int, ok bool) {
	st := lexStarts(oldP, oldMeta)
	prefixP, sufP := parseIdx(st, prefix), parseIdx(st, oldN-suffix)
	prefixLen := 0
	for prefixLen < len(oldEntries) {
		if oldEntries[prefixLen].Ext <= prefixP {
			prefixLen++
		} else {
			break
		}
	}
	suffixStart := len(oldEntries)
	for i := len(oldEntries) - 1; i >= prefixLen; i-- {
		if oldEntries[i].TokStart >= sufP {
			suffixStart = i
		} else {
			break
		}
	}
	prefixKids := append([]int32(nil), oldHs[:prefixLen]...)
	suffixCand := append([]int32(nil), oldHs[suffixStart:]...)
	prefixMeta := append([]EntryMeta(nil), oldEntries[:prefixLen]...)
	suffixMeta := append([]EntryMeta(nil), oldEntries[suffixStart:]...)
	rel, minRel := tailRel(st, oldN, suffixMeta)
	p := &parserW{toks: reuseToks(oldP, prefixP, toksFromMeta(newText, newMeta), prefix), src: newText, b: b, scratch: nil}
	if prefixLen > 0 {
		p.pos = prefixMeta[prefixLen-1].TokEnd
	} else {
		p.pos = 0
	}
	mid := make([]int32, 0)
	midMeta := make([]EntryMeta, 0)
	finishHit := func(adoptFrom int) (int32, []EntryMeta, []int32, []Tok, int, bool) {
		tokDelta := 0
		if adoptFrom < len(suffixMeta) {
			s := suffixMeta[adoptFrom].TokStart
			tokDelta = p.pos - s
			p.toks = adoptTail(p.toks, p.pos, oldP, s, byteDelta)
		}
		adopted := make([]int32, 0, len(suffixCand)-adoptFrom)
		for _, s := range suffixCand[adoptFrom:] {
			adopted = append(adopted, sh.Shift(s, byteDelta, tokDelta))
		}
		children := make([]int32, 0, len(prefixKids)+len(mid)+len(adopted))
		children = append(children, prefixKids...)
		children = append(children, mid...)
		children = append(children, adopted...)
		adoptedMeta := append([]EntryMeta(nil), suffixMeta[adoptFrom:]...)
		outE := make([]EntryMeta, 0, len(prefixMeta)+len(midMeta)+len(adoptedMeta))
		outE = append(outE, prefixMeta...)
		outE = append(outE, midMeta...)
		for i := range adoptedMeta {
			shiftEntryMeta(&adoptedMeta[i], byteDelta, tokDelta)
			outE = append(outE, adoptedMeta[i])
		}
		off, end, tokStart, tokEnd := 0, 0, 0, 0
		if len(outE) > 0 {
			off = outE[0].Off
			end = outE[len(outE)-1].End
			tokStart = outE[0].TokStart
			tokEnd = outE[len(outE)-1].TokEnd
		}
		scratch := append([]int32(nil), children...)
		b.Node(&scratch, 0, 29, uint32(off), uint32(end), uint32(tokStart), uint32(tokEnd))
		if len(scratch) != 1 {
			return 0, nil, nil, nil, 0, false
		}
		recordToks(b, p.toks)
		return scratch[0], outE, children, p.toks, len(prefixKids) + len(adopted), true
	}
	tryHit := func() (int32, []EntryMeta, []int32, []Tok, int, bool) {
		if p.splitEnd > p.pos || len(p.toks)-p.pos > suffix {
			return 0, nil, nil, nil, 0, false
		}
		if len(suffixCand) == 0 {
			if p.pos == len(p.toks) {
				return finishHit(0)
			}
			return 0, nil, nil, nil, 0, false
		}
		for i := range suffixMeta {
			if rel[i] == len(p.toks)-p.pos {
				return finishHit(i)
			}
		}
		return 0, nil, nil, nil, 0, false
	}
	if r, e, hs, ts, n, hit := tryHit(); hit {
		return r, e, hs, ts, n, true
	}
	if len(suffixCand) > 0 && minRel >= 0 && p.splitEnd <= p.pos && len(p.toks)-p.pos < minRel {
		return 0, nil, nil, nil, 0, false
	}
	for {
		if p.pos >= len(p.toks) {
			if len(suffixCand) == 0 && p.pos == len(p.toks) {
				return finishHit(0)
			}
			if r, e, hs, ts, n, hit := tryHit(); hit {
				return r, e, hs, ts, n, true
			}
			return 0, nil, nil, nil, 0, false
		}
		p.maxLook = 0
		sp := p.pos
		fr, pok := p.parseTopOneW()
		if !pok {
			p.pos = sp
			return 0, nil, nil, nil, 0, false
		}
		tokEnd := p.pos
		ext := tokEnd
		if p.maxLook > ext {
			ext = p.maxLook
		}
		end := int(fr.off)
		if fr.present {
			_, e1 := b.SpanOf(fr.h, p.toks)
			end = int(e1)
		}
		midMeta = append(midMeta, EntryMeta{int(fr.tokStart), tokEnd, ext, int(fr.off), end, 0, 1})
		mid = append(mid, fr.h)
		if r, e, hs, ts, n, hit := tryHit(); hit {
			return r, e, hs, ts, n, true
		}
		if len(suffixCand) > 0 && minRel >= 0 && p.splitEnd <= p.pos && len(p.toks)-p.pos < minRel {
			return 0, nil, nil, nil, 0, false
		}
	}
}

// Document is the shared surface of NewDoc (*Doc) and NewDocWith (*DocWith).
type Document interface {
	SetValidate(v bool)
	Text() string
	Root() int32
	Align() *Align
	Edit(edits []Edit) int32
}

// DocWith holds a consumer Builder + optional EntryMeta reuse (W path).
type DocWith struct {
	text     string
	root     int32
	toks     []alignMeta
	ptoks    []Tok
	align    *Align
	validate bool
	b        Builder
	entries []EntryMeta
	entryHs []int32
}

// NewDocWith: *CstBuilder → a Doc whose tree lives in that builder (CST fast path, S3). Other
// builders → DocWith (parserW).
func NewDocWith(src string, b Builder) Document {
	if cb, is := b.(*CstBuilder); is {
		return newDocCst(src, cb)
	}
	return newDocWith(src, b)
}

func newDocWith(src string, b Builder) *DocWith {
	d := &DocWith{text: src, b: b}
	d.toks = scanMeta(src)
	h, entries, entryHs, pt, ok := parseWithMetaW(src, d.toks, b)
	if ok {
		d.root, d.ptoks = h, pt
		d.entries = entries
		d.entryHs = entryHs
	} else {
		d.root = -1
	}
	return d
}

func (d *DocWith) SetValidate(v bool) { d.validate = v }
func (d *DocWith) Text() string       { return d.text }
func (d *DocWith) Root() int32        { return d.root }
func (d *DocWith) Align() *Align      { return d.align }

func (d *DocWith) Edit(edits []Edit) (ret int32) {
	oldText, oldToks := d.text, d.toks
	relexed := 0
	defer func() {
		if rec := recover(); rec != nil {
			d.text = oldText
			for _, e := range edits {
				d.text = applyEdit(d.text, e)
			}
			func() {
				defer func() {
					if recover() != nil {
				d.root = -1
				d.entries = nil
				d.entryHs = nil
						d.toks = nil
						d.align = &Align{OldN: len(oldToks), NewN: 0, Prefix: 0, Suffix: 0, Relexed: 0, Reused: 0}
					}
				}()
				d.toks = scanMeta(d.text)
				h, ne, nhs, pt, ok := parseWithMetaW(d.text, d.toks, d.b)
				if ok {
				d.root, d.ptoks = h, pt
				d.entries = ne
				d.entryHs = nhs
				} else {
				d.root = -1
				d.entries = nil
				d.entryHs = nil
				}
				d.align = &Align{OldN: len(oldToks), NewN: len(d.toks), Prefix: 0, Suffix: 0, Relexed: len(d.toks), Reused: 0}
			}()
			ret = d.root
		}
	}()
	curText := d.text
	curToks := d.toks
	for _, e := range edits {
		stepOldText, stepOldToks := curText, curToks
		n := len(curText)
		start, end := e.Start, e.End
		if start < 0 { start = 0 }
		if start > n { start = n }
		if end < start { end = start }
		if end > n { end = n }
		ins := e.Text
		curText = curText[:start] + ins + curText[end:]
		var stepRelexed int
		curToks, stepRelexed = windowRelexStep(stepOldText, stepOldToks, curText, start, end, ins)
		relexed += stepRelexed
	}
	d.text = curText
	d.toks = curToks
	oldN, newN, prefix, suffix := computeAlignCore(oldText, oldToks, d.text, d.toks)
	byteDelta := len(d.text) - len(oldText)
	reused := 0
	_, hasShift := d.b.(Shifter)
	forceFresh := !hasShift || d.root < 0
	if !forceFresh {
		sh := d.b.(Shifter)
		if got, ne, nhs, ts, n, hit := tryReuseTopW(d.b, sh, d.entryHs, d.entries, d.ptoks, oldToks, d.text, d.toks, byteDelta, oldN, prefix, suffix); hit {
			d.root, d.ptoks = got, ts
			d.entries = ne
			d.entryHs = nhs
			reused = n
		} else {
			h, ne, nhs, pt, ok := parseWithMetaW(d.text, d.toks, d.b)
			if !ok {
				d.toks = scanMeta(d.text)
				h, ne, nhs, pt, ok = parseWithMetaW(d.text, d.toks, d.b)
			}
			if ok {
				d.root, d.ptoks = h, pt
				d.entries = ne
				d.entryHs = nhs
			} else {
				d.root = -1
				d.entries = nil
				d.entryHs = nil
			}
			reused = 0
		}
	} else {
		h, ne, nhs, pt, ok := parseWithMetaW(d.text, d.toks, d.b)
		if !ok {
			d.toks = scanMeta(d.text)
			h, ne, nhs, pt, ok = parseWithMetaW(d.text, d.toks, d.b)
		}
		if ok {
			d.root, d.ptoks = h, pt
			d.entries = ne
			d.entryHs = nhs
		} else {
			d.root = -1
			d.entries = nil
			d.entryHs = nil
		}
		reused = 0
	}
	a := &Align{OldN: oldN, NewN: newN, Prefix: prefix, Suffix: suffix, Relexed: relexed, Reused: reused}
	if d.validate {
		func() {
			defer func() { recover() }()
			v := checkStreamEq(d.text, d.toks)
			a.StreamEq = &v
		}()
		// Non-CST builders: treeEq reports nil (rust SUPPORTS_TREE_EQ=false).
	}
	d.align = a
	ret = d.root
	return
}

// recordToks hands the built-in builders the parse stream their leaves index.
func recordToks(b Builder, ts []Tok) {
	switch x := b.(type) {
	case *CstBuilder:
		x.Toks = ts
	case *SlimBuilder:
		x.Toks = ts
	}
}
func CstJSONWith(b *CstBuilder, root int32) string {
	var buf strings.Builder
	writeJSONWith(b.Nodes, b.Kids, b.Toks, root, &buf)
	return buf.String()
}
func SlimJSONWith(b *SlimBuilder, root int32) string {
	var buf strings.Builder
	writeJSONWith(b.Nodes, b.Kids, b.Toks, root, &buf)
	return buf.String()
}

